files.content:
* { box-sizing: border-box; }
:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  color: #302d26;
  background: #f6ead5;
}
body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #f6ead5;
  background-image: radial-gradient(#d9c6a4 1px, transparent 1px);
  background-size: 18px 18px;
}
.card {
  width: min(100%, 480px);
  padding: clamp(24px, 7vw, 40px);
  border: 3px solid #302d26;
  border-radius: 8px;
  background: #fffaf0;
  box-shadow: 8px 8px 0 #a8bd8b;
}
.pixel-mark {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  margin: 0 auto 18px;
  border: 3px solid #302d26;
  background: #e5a35b;
  font-size: 27px;
  image-rendering: pixelated;
}
.eyebrow { margin: 0; color: #65734e; text-align: center; font-size: .8rem; font-weight: 800; letter-spacing: .14em; }
h1 { margin: 7px 0 4px; text-align: center; font-size: clamp(2rem, 9vw, 2.7rem); line-height: 1.1; }
.intro { margin: 0 0 28px; text-align: center; color: #625d50; }
.converter { margin-bottom: 25px; }
.converter > label { display: block; margin-bottom: 8px; font-weight: 700; }
.input-row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(130px, .8fr); gap: 10px; }
input, select {
  width: 100%; min-height: 52px; padding: 10px 12px;
  border: 2px solid #827a67; border-radius: 5px;
  background: #fff; color: #302d26; font: inherit;
}
input:focus-visible, select:focus-visible { outline: 3px solid #6b8152; outline-offset: 3px; }
input:hover, select:hover { border-color: #65734e; }
.results { padding: 19px; border: 2px solid #d7c8a9; border-radius: 5px; background: #f3f0df; }
h2 { margin: 0 0 12px; font-size: 1rem; }
#result-list { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
#result-list li { display: flex; justify-content: space-between; gap: 12px; align-items: baseline; padding-bottom: 7px; border-bottom: 1px dashed #c8b995; }
#result-list li:last-child { padding-bottom: 0; border: 0; }
.result-value { font-weight: 800; color: #53683d; font-variant-numeric: tabular-nums; }
.note { margin: 20px 0 0; color: #625d50; text-align: center; font-size: .9rem; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 380px) { .input-row { grid-template-columns: 1fr; } }

const amountInput = document.querySelector('#amount');
const unitSelect = document.querySelector('#unit');
const resultList = document.querySelector('#result-list');

const units = [
  { key: 'cups', label: 'Cups', short: 'cups', perCup: 1 },
  { key: 'tablespoons', label: 'Tablespoons', short: 'tbsp', perCup: 16 },
  { key: 'teaspoons', label: 'Teaspoons', short: 'tsp', perCup: 48 },
  { key: 'millilitres', label: 'Millilitres', short: 'ml', perCup: 240 }
];

function renderResults() {
  const amount = Number(amountInput.value);
  const source = units.find((unit) => unit.key === unitSelect.value);
  resultList.replaceChildren();

  if (!Number.isFinite(amount) || amount < 0 || !source) return;

  const cups = amount / source.perCup;
  units.filter((unit) => unit.key !== source.key).forEach((unit) => {
    const item = document.createElement('li');
    const label = document.createElement('span');
    const value = document.createElement('span');
    label.textContent = unit.label;
    value.className = 'result-value';
    value.textContent = `${(cups * unit.perCup).toFixed(1)} ${unit.short}`;
    item.append(label, value);
    resultList.append(item);
  });
}

amountInput.addEventListener('input', renderResults);
unitSelect.addEventListener('change', renderResults);
renderResults();
